import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "../styles/ManageUsers.css";

const MyGigs = () => {
  const [gigs, setGigs] = useState([]);
  const navigate = useNavigate();
  const token = localStorage.getItem("token");

  /**
   * ✅ Fetch user's gigs from the backend
   */
  const fetchGigs = async () => {
    try {
      const response = await axios.get("http://localhost:5000/api/gigs/my-gigs", {
        headers: { Authorization: `Bearer ${token}` },
      });

      console.log("🎸 User's gigs:", response.data);
      setGigs(response.data);
    } catch (err) {
      console.error("❌ Error fetching gigs:", err);
    }
  };

  /**
   * ✅ Handle gig deletion
   */
  const handleDelete = async (gigId) => {
    const confirmDelete = window.confirm("Are you sure you want to delete this gig?");
    if (!confirmDelete) return;

    try {
      await axios.delete(`http://localhost:5000/api/gigs/${gigId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      alert("✅ Gig deleted successfully");
      setGigs((prevGigs) => prevGigs.filter(gig => gig._id !== gigId));
    } catch (err) {
      alert("❌ Could not delete gig");
      console.error("Error deleting gig:", err);
    }
  };

  /**
   * ✅ Fetch gigs on component mount
   */
  useEffect(() => {
    fetchGigs();
  }, []);

  return (
    <div className="manage-users-container">
      <h1>MY GIGS</h1>

      {/* ✅ Navigate to Post Gig Page */}
      <button className="back-btn" onClick={() => navigate("/post-gig")}>
        Post a New Gig
      </button>

      <div className="user-list">
        {gigs.length > 0 ? (
          gigs.map((gig) => (
            <div key={gig._id} className="user-card">
              <span>{gig.title}</span>
              <button onClick={() => navigate(`/gig/${gig._id}`)}>View</button>
              <button onClick={() => navigate(`/edit-gig/${gig._id}`)}>Edit</button>
              <button onClick={() => handleDelete(gig._id)}>Delete</button>
            </div>
          ))
        ) : (
          <p>You have not posted any gigs yet.</p>
        )}
      </div>
    </div>
  );
};

export default MyGigs;
